CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY,name text NOT NULL,description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS domains(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,normalized_domain text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,normalized_domain));
CREATE TABLE IF NOT EXISTS hosts(id uuid PRIMARY KEY,domain_id uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,normalized_host text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(domain_id,normalized_host));
CREATE TABLE IF NOT EXISTS discovery_jobs(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,mode text NOT NULL CHECK(mode IN ('manual','automatic','hybrid')),status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS candidates(id uuid PRIMARY KEY,discovery_job_id uuid NOT NULL REFERENCES discovery_jobs(id) ON DELETE CASCADE,url text NOT NULL,normalized_url text NOT NULL,normalized_domain text NOT NULL,normalized_host text NOT NULL,source_type text NOT NULL,source_id text NOT NULL DEFAULT '',parent_url text NOT NULL DEFAULT '',priority integer NOT NULL DEFAULT 0,confidence double precision NOT NULL DEFAULT 0,status text NOT NULL,attempt_count integer NOT NULL DEFAULT 0,last_error text NOT NULL DEFAULT '',discovered_at timestamptz NOT NULL DEFAULT now(),UNIQUE(discovery_job_id,normalized_url));
CREATE INDEX IF NOT EXISTS candidates_queue_idx ON candidates(discovery_job_id,status,priority DESC);
CREATE TABLE IF NOT EXISTS domain_probes(id uuid PRIMARY KEY,host_id uuid NOT NULL REFERENCES hosts(id) ON DELETE CASCADE,status text NOT NULL,probe_version text NOT NULL,dns_status text NOT NULL DEFAULT '',http_status integer,https_status integer,redirect_target text NOT NULL DEFAULT '',response_time_ms bigint,error_code text NOT NULL DEFAULT '',error_message text NOT NULL DEFAULT '',last_probe_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz);
CREATE TABLE IF NOT EXISTS pages(id uuid PRIMARY KEY,domain_id uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,normalized_url text NOT NULL,status integer,title text NOT NULL DEFAULT '',content_type text NOT NULL DEFAULT '',depth integer NOT NULL DEFAULT 0,fetched_at timestamptz,UNIQUE(domain_id,normalized_url));
CREATE TABLE IF NOT EXISTS technologies(id uuid PRIMARY KEY,domain_id uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,name text NOT NULL,version text NOT NULL DEFAULT '',confidence double precision NOT NULL DEFAULT 0,evidence jsonb NOT NULL DEFAULT '[]',source_url text NOT NULL DEFAULT '',detected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS contacts(id uuid PRIMARY KEY,domain_id uuid NOT NULL REFERENCES domains(id) ON DELETE CASCADE,type text NOT NULL,value text NOT NULL,normalized_value text NOT NULL,source_url text NOT NULL DEFAULT '',detected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_errors(id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES discovery_jobs(id) ON DELETE CASCADE,category text NOT NULL,code text NOT NULL DEFAULT '',message text NOT NULL,retryable boolean NOT NULL DEFAULT false,attempt integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());